Build your own connector using fuse-connector-sdk. See the Writing a Connector section. Implement two traits: #[async_trait]
pub trait FederatedConnector: Send + Sync { fn id(&self) -> &str; fn connector_type(&self) -> &str; fn capabilities(&self) -> ConnectorCapabilities; async fn health_check(&self) -> Result<HealthStatus>; async fn discover_schemas(&self) -> Result<Vec<SchemaInfo>>; async fn get_schema(&self, table: &str) -> Result<Schema>; fn table_names(&self) -> Vec<String>; async fn get_table_schema(&self, table: &str) -> Result<Schema>; async fn execute(&self, query: &SubQuery) -> Result<Vec<RecordBatch>>; async fn execute_streaming(&self, query: &SubQuery) -> Result<Pin<Box<dyn Stream<Item = Result<RecordBatch>> + Send>>>;
} pub trait ConnectorFactory: Send + Sync { fn connector_type(&self) -> &str; fn create(&self, config: &ConnectorConfig) -> Result<Arc<dyn FederatedConnector>>;
} Register your factory in main.rs: registry.register_factory(Arc::new(MyConnectorFactory)); The connector is then available via fuse.toml: [[connector]]
id = "my_source"
connector_type = "my-connector"
